def semver_sort(versions):
    def parse(v):
        # strip build metadata
        core_and_pre = v.split('+', 1)[0]
        if '-' in core_and_pre:
            core, pre = core_and_pre.split('-', 1)
        else:
            core, pre = core_and_pre, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            has_pre = 1  # no prerelease -> sorts after
            pre_key = ()
        else:
            has_pre = 0  # prerelease present -> sorts before
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
            pre_key = tuple(pre_key)

        return (major, minor, patch, has_pre, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for i, v in indexed]

